package ru.mytv.launcher;
import android.content.*;
import android.graphics.*;
import android.os.SystemClock;
import android.text.Html;
import org.json.*;
import java.io.*;
import java.net.*;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.util.*;
public final class PhotoCatalog {
 static final String[] TOPICS={"mountain lake landscape","forest landscape","ocean coast landscape","waterfall landscape","alpine valley landscape","desert dunes landscape","autumn lake landscape","snow mountain landscape","green hills landscape","fjord landscape","island landscape","sunset landscape"};
 static final String[] RESERVE={"1464822759023-fed622ff2c3b","1470770841072-f978cf4d019e","1501785888041-af3ef285b470"};
 final SharedPreferences prefs;final List<ArrayDeque<Item>> queues=Arrays.asList(new ArrayDeque<Item>(),new ArrayDeque<Item>());final LinkedHashSet<String> recent=new LinkedHashSet<>();final long[] pauseUntil=new long[2];final Random random=new Random();volatile boolean closed;volatile HttpURLConnection active;int turn,cursor;long deadline;
 static final class Item {final String url,title,author,source,license,page;Item(String u,String t,String a,String s,String l,String p){url=u;title=t;author=a;source=s;license=l;page=p;}String caption(){return (title.isEmpty()?"":title+"\n")+source+(author.isEmpty()?"":" · "+author)+(license.isEmpty()?"":" · "+license);}}
 static final class Image {final Bitmap bitmap;final Item item;final String key;Image(Bitmap b,Item i,String k){bitmap=b;item=i;key=k;}}
 PhotoCatalog(Context c){prefs=c.getApplicationContext().getSharedPreferences("photo_history",0);cursor=prefs.getInt("cursor",random.nextInt(120));turn=random.nextInt(2);try{JSONArray a=new JSONArray(prefs.getString("recent","[]"));for(int i=0;i<a.length();i++)recent.add(a.getString(i));}catch(Exception ignored){}for(int i=0;i<2;i++)pauseUntil[i]=prefs.getLong("pause"+i,0);}
 synchronized boolean seen(String key){return recent.contains(key);}
 synchronized void shown(Image image){if(closed)return;for(String k:new String[]{image.item.url,image.key}){recent.remove(k);recent.add(k);}while(recent.size()>256)recent.remove(recent.iterator().next());prefs.edit().putString("recent",new JSONArray(new ArrayList<String>(recent)).toString()).apply();}
 void close(){closed=true;HttpURLConnection c=active;if(c!=null)c.disconnect();}
 void check()throws IOException{if(closed||Thread.currentThread().isInterrupted())throw new InterruptedIOException("Загрузка отменена");if(SystemClock.elapsedRealtime()>=deadline)throw new SocketTimeoutException("Истекло время поиска фотографии");}
 byte[] get(String value,int limit)throws Exception{URL url=new URL(value);HttpURLConnection c=null;try{for(int n=0;;n++){check();if(!"https".equalsIgnoreCase(url.getProtocol()))throw new IOException("Разрешены только HTTPS-фотографии");c=(HttpURLConnection)url.openConnection();active=c;c.setUseCaches(false);c.setInstanceFollowRedirects(false);int timeout=(int)Math.max(1,Math.min(6000,deadline-SystemClock.elapsedRealtime()));c.setConnectTimeout(timeout);c.setReadTimeout(timeout);c.setRequestProperty("User-Agent","MyTVLauncher/0.3.6 (https://github.com/ncuKC/my-tv-launcher-app)");int status=c.getResponseCode();if(status>=300&&status<400){String to=c.getHeaderField("Location");c.disconnect();if(to==null||n>=4)throw new IOException("Ошибка перенаправления");url=new URL(url,to);continue;}if(status!=200)throw new IOException("HTTP "+status);if(c.getContentLengthLong()>limit)throw new IOException("Фотография или ответ слишком велики");break;}ByteArrayOutputStream out=new ByteArrayOutputStream();try(InputStream in=c.getInputStream()){byte[] b=new byte[8192];int n,total=0;while((n=in.read(b))!=-1){check();total+=n;if(total>limit)throw new IOException("Превышен размер ответа");out.write(b,0,n);}}return out.toByteArray();}finally{if(c!=null)c.disconnect();active=null;}}
 static String text(String s){if(s==null)return "";return Scenes.clean(Html.fromHtml(s,Html.FROM_HTML_MODE_LEGACY).toString());}
 static boolean safe(String s){return s!=null&&s.startsWith("https://");}
 static String meta(JSONObject o,String key){JSONObject v=o.optJSONObject(key);return v==null?"":text(v.optString("value",""));}
 void refill(int provider)throws Exception{int number=cursor++;prefs.edit().putInt("cursor",cursor).apply();String term=TOPICS[Math.floorMod(number,TOPICS.length)];String query=URLEncoder.encode(term,"UTF-8");ArrayList<Item> found=new ArrayList<>();if(provider==0){String search=URLEncoder.encode(term+" filemime:image/jpeg","UTF-8");String url="https://commons.wikimedia.org/w/api.php?action=query&format=json&formatversion=2&generator=search&gsrnamespace=6&gsrlimit=20&gsroffset="+(Math.floorMod(number/TOPICS.length,5)*20)+"&gsrsearch="+search+"&prop=imageinfo&iiprop=url%7Csize%7Cmime%7Cextmetadata&iiurlwidth=1920&iiextmetadatalanguage=en";JSONObject root=new JSONObject(new String(get(url,2097152),StandardCharsets.UTF_8));if(root.has("error"))throw new IOException("Ошибка API Commons: "+root.getJSONObject("error").optString("code"));JSONObject q=root.optJSONObject("query");JSONArray pages=q==null?null:q.optJSONArray("pages");if(pages!=null)for(int j=0;j<pages.length();j++){JSONObject page=pages.getJSONObject(j);JSONArray infos=page.optJSONArray("imageinfo");if(infos==null||infos.length()==0)continue;JSONObject i=infos.getJSONObject(0);int w=i.optInt("width"),h=i.optInt("height");if(w<1280||h<720||w<h*1.3||w>h*3.0||!"image/jpeg".equals(i.optString("mime")))continue;JSONObject m=i.optJSONObject("extmetadata");if(m==null)continue;String license=meta(m,"LicenseShortName"),terms=meta(m,"UsageTerms");String lower=(license+" "+terms).toLowerCase(Locale.ROOT);if(!lower.contains("cc0")&&!lower.contains("public domain")&&!lower.contains("publicdomain"))continue;String u=i.optString("thumburl",i.optString("url"));if(!safe(u))continue;String title=meta(m,"ObjectName");if(title.isEmpty())title=text(page.optString("title")).replaceFirst("^File:","");found.add(new Item(u,title,meta(m,"Artist"),"Wikimedia Commons",license,i.optString("descriptionurl")));}}else{String url="https://api.openverse.org/v1/images/?q="+query+"&page_size=20&page="+(1+Math.floorMod(number/TOPICS.length,3))+"&license=cc0,pdm&category=photograph&aspect_ratio=wide&size=large&extension=jpg,jpeg&excluded_source=wikimedia&mature=false";JSONArray results=new JSONObject(new String(get(url,2097152),StandardCharsets.UTF_8)).getJSONArray("results");for(int j=0;j<results.length();j++){JSONObject i=results.getJSONObject(j);String l=i.optString("license"),u=i.optString("url");int w=i.optInt("width"),h=i.optInt("height");if(!safe(u)||w<1280||h<720||w<h*1.3||w>h*3.0||(!"cc0".equals(l)&&!"pdm".equals(l)))continue;found.add(new Item(u,text(i.optString("title")),text(i.optString("creator")),"Openverse / "+text(i.optString("source",i.optString("provider"))),l.toUpperCase(Locale.ROOT),i.optString("foreign_landing_url")));}}Collections.shuffle(found,random);for(Item i:found)if(!seen(i.url))queues.get(provider).add(i);if(queues.get(provider).isEmpty())throw new IOException("В подборке нет новых подходящих фото CC0 / Public Domain");}
 Image decode(Item item)throws Exception{check();if(seen(item.url))throw new IOException("Недавно показанное фото");byte[] bytes=get(item.url,8388608);String key=Base64.getEncoder().encodeToString(MessageDigest.getInstance("SHA-256").digest(bytes));if(seen(key))throw new IOException("Повтор фотографии");BitmapFactory.Options o=new BitmapFactory.Options();o.inJustDecodeBounds=true;BitmapFactory.decodeByteArray(bytes,0,bytes.length,o);if(o.outWidth<1280||o.outHeight<720||o.outWidth<o.outHeight*1.3||o.outWidth>o.outHeight*3.0)throw new IOException("Неподходящий размер или формат фото");o.inSampleSize=1;while(o.outWidth/o.inSampleSize>1920||o.outHeight/o.inSampleSize>1080)o.inSampleSize*=2;o.inJustDecodeBounds=false;o.inPreferredConfig=Bitmap.Config.RGB_565;Bitmap b=BitmapFactory.decodeByteArray(bytes,0,bytes.length,o);if(b==null)throw new IOException("Не удалось декодировать фото");return new Image(b,item,key);}
 Image next()throws Exception{deadline=SystemClock.elapsedRealtime()+30000;StringBuilder errors=new StringBuilder();int first=turn++%2;for(int step=0;step<2;step++){int p=(first+step)%2;String name=p==0?"Commons":"Openverse";if(System.currentTimeMillis()<pauseUntil[p]){errors.append(name).append(": временная пауза; " );continue;}try{if(queues.get(p).isEmpty())refill(p);for(int attempt=0;attempt<2&&!queues.get(p).isEmpty();attempt++){Item item=queues.get(p).removeFirst();try{return decode(item);}catch(Exception e){check();errors.append(name).append(": ").append(Scenes.clean(e.getMessage())).append("; ");}}}catch(Exception e){check();String message=e.getMessage();errors.append(name).append(": ").append(Scenes.clean(message)).append("; ");pauseUntil[p]=System.currentTimeMillis()+(message!=null&&message.contains("HTTP 429")?900000:120000);prefs.edit().putLong("pause"+p,pauseUntil[p]).apply();}}for(int n=0;n<RESERVE.length;n++){String id=RESERVE[Math.floorMod(cursor+n,RESERVE.length)];Item item=new Item("https://images.unsplash.com/photo-"+id+"?fm=jpg&fit=crop&w=1920&h=1080&q=80","","","Unsplash — резерв из 3 фото","","");if(seen(item.url))continue;try{return decode(item);}catch(Exception e){check();errors.append("Unsplash: ").append(Scenes.clean(e.getMessage())).append("; ");break;}}throw new IOException(errors.length()==0?"Новые фотографии пока недоступны":errors.toString());}
}
